<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Resources\WalletResource; use App\Models\Wallet; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
final class AdminWalletController { public function index(Request $request): JsonResponse { abort_unless(app(\App\Policies\AdminWalletPolicy::class)->viewAny($request->user()),403); $query=Wallet::with(['owner.user','currencyAccounts.currency','statusHistory.actor']); if($request->filled('status'))$query->where('status',$request->string('status')); if($request->filled('currency'))$query->whereHas('currencyAccounts.currency',fn($q)=>$q->where('code',strtoupper($request->string('currency')))); $wallets=$query->latest()->paginate(10); return response()->json(['data'=>WalletResource::collection($wallets->items()),'meta'=>['current_page'=>$wallets->currentPage(),'last_page'=>$wallets->lastPage(),'per_page'=>10,'total'=>$wallets->total()]]); } public function show(Request $request, Wallet $wallet): JsonResponse { abort_unless(app(\App\Policies\AdminWalletPolicy::class)->view($request->user(),$wallet),403); return response()->json(['data'=>new WalletResource($wallet->load(['owner.user','currencyAccounts.currency','statusHistory.actor']))]); } }
